INSERT INTO `dish` VALUES (4, '草莓蛋糕', 7, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/378c3a44-199a-414b-83a1-b1659b627349_20220208172843_6364a.jpg', '草莓蛋糕，由新鲜草莓和奶油制作而成，口感丝滑', 0, '2025-03-26 14:38:32', '2026-08-20 12:37:08', 13, 0, 100);
INSERT INTO `dish` VALUES (5, '铁锅牛肉面', 25, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/416dcf1e-c780-430b-982f-223236f34e44_3134.jpg_wh860.jpg', '铁锅牛肉面是以牛腱肉、切面等为主要材料制作的食物，口味鲜香，为中华传统面食。', 0, NULL, '2026-08-11 15:00:45', 3, 0, 98);
INSERT INTO `dish` VALUES (13, '卤制红烧肉', 15.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/0476a097-9ae6-4e92-9a2c-910837adf407_3906.jpg_wh860.jpg', '五花肉为制作主料 ， 肥而不腻，香甜松软，营养丰富，入口即化。', 0, NULL, '2026-08-11 15:02:25', 3, 0, 100);
INSERT INTO `dish` VALUES (14, '水果沙拉', 16.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/5e735944-b27d-4228-ba8f-9617c18b1755_0995.jpg_wh860.png', '精制水果沙拉盘，包含芒果、蓝莓、草莓等新鲜水果。', 0, NULL, '2026-08-11 15:04:05', 13, 0, 100);
INSERT INTO `dish` VALUES (15, '青椒炒肉', 15.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/0aeb7eef-2767-4716-b48d-85d4afb4960d_25762690_143121527122_2.jpg', '青椒炒肉是一道以青椒、猪肉为主要食材烹制而成的京菜，口味辣。 味道可口，营养丰富', 0, NULL, '2026-08-11 15:08:55', 3, 0, 100);
INSERT INTO `dish` VALUES (17, '红烧鲤鱼', 18.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/ab9da201-d080-4d00-bdf6-cb48d13483c7_OIP-C.jpg', '红烧鲤鱼的烹饪技巧以红烧为主，口味属于咸鲜，呈黄色，鱼嫩蘑香，汁浓味美。', 0, NULL, '2026-08-11 15:10:13', 3, 0, 100);
INSERT INTO `dish` VALUES (18, '香辣鸡腿堡', 10.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/ec826498-f04d-454a-b196-4920165e220e_25234857_160807869100_2.jpg', '香辣鸡腿堡，由精品鸡腿肉、生菜叶、芝士片自作而成，香辣可口。', 0, NULL, '2026-08-11 15:12:51', 14, 0, 100);
INSERT INTO `dish` VALUES (19, '可乐', 3, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/e54fc080-1bb3-4b05-8931-90ef03af3b5a_550df7ea4bc6ddcd.jpg', '小瓶瓶装可口可乐', 0, NULL, '2026-08-11 15:14:38', 5, 0, 96);
INSERT INTO `dish` VALUES (20, '铁板龙虾', 18.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/3298e766-2772-473d-a681-25c85e65181c_27370257_093656473039_2.jpg', '铁板龙虾，由新鲜龙虾烹饪而成，香辣可口。', 0, NULL, '2026-08-11 15:17:39', 3, 0, 100);
INSERT INTO `dish` VALUES (21, '红烧牛肉片', 28.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/1fbee7e4-768e-4707-9108-bb05587e894d_R-C.jpg', '红烧牛肉片，由新鲜牛肉蒸煮而成，香辣可口，色香味俱全', 0, NULL, '2026-08-11 15:19:42', 3, 0, 99);
INSERT INTO `dish` VALUES (22, '龙虾火锅', 38.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/17715ec8-4f92-4193-93f2-e37b572a1257_23168869_104855242364_2.jpg', '龙虾火锅，物美价廉', 0, NULL, '2026-08-11 15:22:12', 3, 0, 100);
INSERT INTO `dish` VALUES (23, '坚果500g', 18.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/a194544b-2fba-4023-a777-882c4d695b81_0370.jpg_wh860.jpg', '由杏仁、巴西坚果、 腰果、榛子、澳洲坚果、山核桃、松子、开心果、核桃、葵花子和花生等混装', 0, NULL, '2026-08-11 15:23:29', 4, 0, 100);
INSERT INTO `dish` VALUES (24, '腰果500g', 28.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/888fd568-bfde-47ef-a746-9051bf7b678f_OIP-C (1).jpg', '营养价值非常高，含有丰富的蛋白质、脂肪、矿物质和维生素。', 0, NULL, '2026-08-11 15:25:16', 4, 0, 100);
INSERT INTO `dish` VALUES (25, '开心果500g', 19.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/f933e893-f32c-4788-aec7-a6a38ba0b1d8_2368.jpg_wh860.jpg', '开心果果仁是高营养的食品，每100克果仁含维生素A20微克，叶酸59微克，同时含有多种矿物质等', 0, NULL, '2026-08-11 15:26:28', 4, 0, 100);
INSERT INTO `dish` VALUES (26, '杏仁500g', 18.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/95b76bd3-2cad-441a-9a89-b2ecaf7275a6_3476.jpg_wh860.jpg', '杏仁含有丰富的营养成分，特别富含蛋白质、脂肪、矿物质和维生素', 0, NULL, '2026-08-11 15:29:00', 4, 0, 100);
INSERT INTO `dish` VALUES (27, '核桃仁500g', 18.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/21347377-981b-444e-ba0a-c5afea0d07a2_4jVK7hiejL.jpg', '核桃仁含有丰富的营养素，是很好的滋补品和食品加工原料，含脂肪65%左右，蛋白质15%左右，碳水化合物10%以上', 0, NULL, '2026-08-11 15:31:05', 4, 0, 100);
INSERT INTO `dish` VALUES (28, '夏威夷果', 28.8, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/d043ee34-5d5b-436e-8f79-89d8516cc3bc_31527039_204356348123_2.jpg', '夏威夷果 果仁营养丰富，其外果皮青绿色，内果皮坚硬，呈褐色，单果重15—16克，含油量70％左右， 蛋白质 9％', 0, NULL, '2026-08-11 15:33:45', 4, 0, 100);
INSERT INTO `dish` VALUES (29, '炒板栗200g', 10, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/1984a523-d1a3-432c-9bc5-358e3d939295_R-C (1).jpg', '口感丰富多样，既有坚实的质感，又有糯甜的细腻。咬上一口，板栗的香气在口腔中弥漫开来，让人感受到秋天的浓郁气 …', 0, NULL, '2026-08-11 15:35:18', 4, 0, 100);
INSERT INTO `dish` VALUES (30, '柠檬水500ml', 3.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/32dd305a-5083-4d81-99aa-db5529c8c296_17880451_121829188121_2.jpg', '冰镇柠檬水，炎日必备，清凉解渴', 0, NULL, '2026-08-11 15:36:34', 5, 0, 100);
INSERT INTO `dish` VALUES (31, '茉莉花茶', 15, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/c5dd5175-b116-4732-badc-c20265dcc0c7_3988.jpg_wh860.jpg', '甄选横县茉莉、高山春茶制成茉莉花茶、搭配醇香牛乳、花香入茶骨，口感清爽轻负担', 0, NULL, '2026-08-11 15:38:03', 5, 0, 100);
INSERT INTO `dish` VALUES (32, '芝士绿茶', 18.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/7ce6a66b-c4e8-440c-900b-ee9cccb72c08_26830102_102819144086_2.jpg', '芝士绿茶，灵感来自喜茶十年经典芝士茶。 特别添加胶原蛋白肽。 低脂低糖，一瓶的能量小于一个苹果', 0, NULL, '2026-08-11 15:39:59', 5, 0, 100);
INSERT INTO `dish` VALUES (33, '百香双重奏', 10.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/9df1c528-1a35-435d-b055-80ef7ef768c4_t01c44b0bfa8c1eebff.jpg', '满满百香果，超多维生素C搭配珍珠和椰果，口感兼具Q弹和软糯', 0, NULL, '2026-08-11 15:41:17', 5, 0, 100);
INSERT INTO `dish` VALUES (34, '超A葡萄冰', 17.5, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/79c7eff6-f84a-4e28-a15a-95f54a35f28c_24333907_213224622217_2.jpg', '手剥时令葡萄，融合Q弹茉莉冻，不含奶盖口感更轻盈', 0, NULL, '2026-08-11 15:43:24', 5, 0, 99);
INSERT INTO `dish` VALUES (36, '布蕾脆脆奶芙', 18, 'https://wenle-restaurant.oss-cn-beijing.aliyuncs.com/images/5f9e10e6-6260-4692-9564-79ef906932bd_OIP-C.jpg', '入口即化的奶芙搭配Q弹有嚼劲的珍珠，碰撞出不一样的味蕾体验。', 0, NULL, '2026-08-11 15:45:50', 5, 0, 100);
